return [ 'version' => '2.0', 'service' => '<p>Amazon EventBridge event bus API. An event bus receives events published by your applications and AWS services, stores them for a configurable retention period, and delivers them to subscribers. A subscriber filters events, optionally transforms them, and invokes a target such as Lambda, SQS, SNS, Kinesis, Step Functions, or an HTTP endpoint. The API manages event buses, subscribers, event sources, resource policies, and tags, and publishes events through PutEvents and PutRawEvents.</p>', 'operations' => [ 'CreateEventBus' => '<p>Creates an event bus. Provisioning is asynchronous: the bus is returned in the CREATING state and transitions to ACTIVE when ready (see the EventBusActive waiter). Retries carrying the same ClientToken are idempotent.</p>', 'CreateEventSource' => '<p>Creates an EventSource, which forwards events from an origin (an AWS service or another account) onto an event bus. The bus must be ACTIVE. Retries carrying the same ClientToken are idempotent.</p>', 'CreateSubscriber' => '<p>Creates a subscriber on an event bus, which delivers matching events to the configured target. The bus must be ACTIVE. Retries carrying the same ClientToken are idempotent.</p>', 'DeleteEventBus' => '<p>Deletes an event bus. Deletion is asynchronous: the bus moves to DELETING and disappears when complete (see the EventBusDeleted waiter). A bus with subscribers or event sources cannot be deleted.</p>', 'DeleteEventSource' => '<p>Deletes an EventSource. Forwarding from its origin stops.</p>', 'DeleteResourcePolicy' => '<p>Deletes the named resource policy attached to an event bus.</p>', 'DeleteSubscriber' => '<p>Deletes a subscriber. Events are no longer delivered to its target.</p>', 'DescribeEventBus' => '<p>Returns the full configuration and lifecycle state of an event bus.</p>', 'DescribeEventSource' => '<p>Returns the full configuration and lifecycle state of an EventSource.</p>', 'DescribeSubscriber' => '<p>Returns the full configuration and state of a subscriber.</p>', 'GetResourcePolicy' => '<p>Returns the named resource policy attached to an event bus. Fails with ResourceNotFoundException when the event bus or the named policy does not exist.</p>', 'ListEventBuses' => '<p>Lists the event buses visible to the caller: buses the account owns and buses shared with it through AWS RAM. Shared entries carry identity fields only (Name, EventBusArn, EventBusAccountId); owned entries carry every summary field. Set EventBusAccountId to scope the list to one owner account.</p>', 'ListEventSources' => '<p>Lists EventSources as summaries. By default the list spans the EventSources the caller account owns; set EventBusArn to scope it to one bus. Use DescribeEventSource to retrieve full configuration.</p>', 'ListResourcePolicies' => '<p>Lists the resource policies attached to an event bus as summaries (policy name and revision ID). Use GetResourcePolicy to retrieve a policy document.</p>', 'ListSubscribers' => '<p>Lists subscribers as summaries. By default the list spans the subscribers the caller account owns across all buses; set EventBusArn to scope it to one bus. Use DescribeSubscriber to retrieve full configuration.</p>', 'ListTagsForResource' => '<p>Lists the tags on an event bus, subscriber, or event source.</p>', 'PutEvents' => '<p>Publishes events to an event bus.</p>', 'PutRawEvents' => '<p>Publishes pre-shaped events to an event bus.</p>', 'PutResourcePolicy' => '<p>Attaches a named resource policy to an event bus — the only resource type that supports policies; other resource ARNs are rejected. Each bus holds two named policies: &quot;default&quot; (customer-managed, full IAM policy language including Deny) and &quot;AWS_RAM&quot; (written exclusively by AWS Resource Access Manager to reflect resource shares). Both policies are evaluated on cross-account authorization; an explicit Deny in either overrides an Allow in the other. Operations that omit PolicyName target &quot;default&quot;. A &quot;default&quot; policy that would grant public access is rejected with PublicPolicyException and is not attached; this check is always on and cannot be disabled.</p>', 'RevokeResource' => '<p>Revokes a subscriber or an EventSource. The bus owner calls this to withdraw a misbehaving resource attached to their bus. Revocation is terminal: there is no operation that clears it. A revoked resource refuses mutating operations with InvalidStateException; delete stays available for cleanup.</p>', 'TagResource' => '<p>Adds or replaces tags on an event bus, subscriber, or event source.</p>', 'UntagResource' => '<p>Removes tags from an event bus, subscriber, or event source.</p>', 'UpdateEventBus' => '<p>Updates an event bus. The update is asynchronous: the bus moves to UPDATING and returns to ACTIVE when the change is applied. Fields omitted from the request are left unchanged.</p>', 'UpdateEventSource' => '<p>Updates an EventSource. Fields omitted from the request are left unchanged.</p>', 'UpdateSubscriber' => '<p>Updates a subscriber. Fields omitted from the request are left unchanged.</p>', ], 'shapes' => [ 'AccessDeniedException' => [ 'base' => '<p>The caller does not have the permissions required to perform the operation. This error is also returned when the operation cannot use the AWS KMS key for the event bus.</p>', 'refs' => [], ], 'AccountId' => [ 'base' => '<p>AWS Account Id.</p>', 'refs' => [ 'EventBusSummary$EventBusAccountId' => NULL, 'EventSourceSummary$EventSourceAccountId' => NULL, 'ListEventBusesRequest$EventBusAccountId' => NULL, 'SubscriberSummary$SubscriberAccountId' => NULL, ], ], 'AwsServiceEventsSourceConfiguration' => [ 'base' => '<p>Configuration for forwarding a single AWS service\'s events from the account\'s default event bus.</p>', 'refs' => [ 'EventSourceConfiguration$AwsServiceEventsConfiguration' => NULL, ], ], 'AwsServiceEventsSourceConfigurationPatternString' => [ 'base' => '<p>An event pattern, as a JSON string, that selects which events match.</p>', 'refs' => [ 'AwsServiceEventsSourceConfiguration$Pattern' => '<p>A filter pattern, as a JSON string, that defines which of the service\'s events are forwarded to the event bus. Do not include source, account, or region as top-level fields. If no pattern is specified, all events from the service are forwarded.</p>', ], ], 'AwsServiceSource' => [ 'base' => '<p>A single AWS service source identifier, e.g. &quot;aws.s3&quot;. Wildcards and lists are rejected.</p>', 'refs' => [ 'AwsServiceEventsSourceConfiguration$AwsService' => NULL, ], ], 'BatchConfiguration' => [ 'base' => '<p>Batching configuration for a subscriber.</p>', 'refs' => [ 'CreateSubscriberRequest$BatchConfiguration' => NULL, 'DescribeSubscriberResponse$BatchConfiguration' => NULL, 'UpdateSubscriberRequest$BatchConfiguration' => NULL, ], ], 'BatchConfigurationMaxBatchSizeInteger' => [ 'base' => '<p>Nullable integer — no default, absence means &quot;not set&quot;.</p>', 'refs' => [ 'BatchConfiguration$MaxBatchSize' => '<p>The maximum number of events to include in a single batch delivered to the target. The service delivers up to this many events per batch; fewer may be delivered when the batch window elapses or the target\'s per-batch limit is smaller. This is a maximum, not a guaranteed count. Valid range is 1-500 (default: 10, or the target API\'s per-batch maximum). The resolved value applied by the service is returned on read.</p>', ], ], 'BatchConfigurationMaxBatchWindowInSecondsInteger' => [ 'base' => '<p>Nullable integer — no default, absence means &quot;not set&quot;.</p>', 'refs' => [ 'BatchConfiguration$MaxBatchWindowInSeconds' => '<p>The maximum time in seconds to wait for a batch to fill before delivering it to the target. This is a maximum; a batch may be delivered sooner if it reaches MaxBatchSize or another delivery condition is met. Valid range is 0-300 (default: 0, meaning no wait). The resolved value applied by the service is always returned on read.</p>', ], ], 'Boolean' => [ 'base' => NULL, 'refs' => [ 'DescribeEventSourceResponse$Revoked' => '<p>True when the bus owner has withdrawn this EventSource. Present only when true, so an absent member means the EventSource is not revoked. Revocation is terminal: it never returns to false. Mutating operations on a revoked EventSource fail with InvalidStateException, except DeleteEventSource, which stays available so a revoked EventSource can still be cleaned up.</p>', 'DescribeSubscriberResponse$Revoked' => '<p>True when the bus owner has revoked this subscriber. Present only when true, so an absent member means the subscriber is not revoked. Revocation is terminal: it never returns to false. Mutating operations on a revoked subscriber fail with InvalidStateException, except DeleteSubscriber, which stays available so a revoked subscriber can still be cleaned up.</p>', 'EventSourceSummary$Revoked' => '<p>True when the bus owner has withdrawn this EventSource. Present only when true, so a bus owner listing EventSources sees at a glance which ones they revoked. See DescribeEventSourceResponse$Revoked.</p>', 'SubscriberSummary$Revoked' => '<p>True when the bus owner has revoked this subscriber. Present only when true, so a bus owner listing subscribers sees at a glance which ones they revoked. See DescribeSubscriberResponse$Revoked.</p>', ], ], 'BusState' => [ 'base' => '<p>Lifecycle state of an event bus.</p> <ul> <li>CREATING: Bus creation is in progress.</li> <li>CREATE_FAILED: Bus creation failed; see StateReason. The bus cannot be recovered or recreated in place: delete it with DeleteEventBus, then create a new bus.</li> <li>ACTIVE: Bus is fully operational and can accept events.</li> <li>UPDATING: Bus update is in progress.</li> <li>UPDATE_FAILED: Bus update failed; the bus remains operational with its previous configuration.</li> <li>DELETING: Bus deletion is actively in progress.</li> <li>DELETE_FAILED: Bus deletion failed; see StateReason. Retry DeleteEventBus after removing subsc